const headers = $json.headers || {};
const body = $json.body || {};
const supplied = String(headers['x-n8n-secret'] || headers['X-N8N-Secret'] || '');
const expected = String($env.N8N_SECRET || '');
const authorized = expected.length > 0 && supplied === expected;
const positive = (value) => Number.isInteger(Number(value)) && Number(value) > 0;
const c = body.contact || {};
const r = body.reservation || {};
const d = body.data || {};
const validContact = c.type === 'email' ? /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(c.value || '')) : c.type === 'whatsapp' ? /^\+52\d{10}$/.test(String(c.value || '')) : false;
const valid = Number(body.schema_version) === 1 && body.event === 'reservation.schedule_change' && positive(body.source_id) && positive(body.reservation_id) && [1, 2].includes(Number(body.attempt)) && validContact && body.recipient && String(body.recipient.name || '').trim() !== '' && /^\d{4}-\d{2}-\d{2}$/.test(String(r.date || '')) && /^\d{2}:\d{2}$/.test(String(r.time || '')) && positive(r.guests) && /^https?:\/\/[^\s]+$/i.test(String(d.management_url || '')) && !Number.isNaN(Date.parse(String(d.access_expires_at || '')));
return { json: { authorized, valid, accepted: authorized && valid, notification: authorized && valid ? body : null } };

if (!$json.accepted || !$json.notification) return [];
const n = $json.notification;
const r = n.reservation;
const d = n.data;
const values = [n.recipient.name, r.date, r.time, d.management_url];
return { json: { ...n, email_subject: 'Necesitamos ajustar tu reservación', email_text: `Hola ${n.recipient.name},

Un cambio en nuestro horario afecta tu reservación del ${r.date} a las ${r.time}.

Elige otro horario o cancela tu reservación aquí:
${d.management_url}

Este acceso vence el ${d.access_expires_at}.`, whatsapp_template: 'reservation_schedule_change', whatsapp_components: { component: [{ type: 'body', bodyParameters: { parameter: values.map((value) => ({ type: 'text', text: String(value) })) } }] } } };

const n = $json || {};
const contact = n.contact || {};
const data = n.data || {};
if (contact.type !== 'email') return [];
return { json: { schema_version: n.schema_version, event: n.event, source_id: n.source_id, reservation_id: n.reservation_id, attempt: n.attempt, channel: 'email', to: String(contact.value || ''), subject: String(n.email_subject || ''), message: String(n.email_text || ''), purpose: String(data.purpose || '') } };

const n = $json || {};
const contact = n.contact || {};
const data = n.data || {};
if (contact.type !== 'whatsapp') return [];
return { json: { schema_version: n.schema_version, event: n.event, source_id: n.source_id, reservation_id: n.reservation_id, attempt: n.attempt, channel: 'whatsapp', to: String(contact.value || ''), template: String(n.whatsapp_template || ''), components: n.whatsapp_components || {}, purpose: String(data.purpose || '') } };
